{"code": "from e14c.web import fetch_parsed_page
urls = {
'doumont_oral':'https://www.cs.tufts.edu/~nr/cs257/archive/jean-luc-doumont/oral.pdf',
'microsoft_access':'https://support.microsoft.com/en-US/accessibility/powerpoint/make-your-powerpoint-presentations-accessible-to-people-with-disabilities',
'w3c_media':'https://www.w3.org/WAI/media/av/av-content/',
'nature_structure':'https://www.nature.com/scitable/topicpage/oral-presentation-structure-13900387/',
'mit_slides':'https://mitcommlab.mit.edu/nse/commkit/slideshow/'
}
pages={}
for k,u in urls.items():
    try:
        pages[k]=await fetch_parsed_page(u)
        print(k, len(pages[k]), pages[k][:800].replace('\n',' '))
    except Exception as e: print('ERR',k,type(e).__name__,str(e)[:200])", "display_text": "Reading primary guidance on oral delivery, slide accessibility, media, and talk structure"}

{"code": "import re
for key in ['microsoft_access','w3c_media','nature_structure','mit_slides']:
    text=pages[key]
    print('\n###',key)
    for term in {'microsoft_access':['contrast','reading order','alt text','captions','accessibility checker'],
                 'w3c_media':['captions','transcript','audio description'],
                 'nature_structure':['questions','rehears','audience','delivery','conclusion'],
                 'mit_slides':['audience','question','accessib','backup','rehears']}[key]:
        inds=[m.start() for m in re.finditer(term,text,re.I)]
        if inds:
            i=inds[0]; print('\n',term,':',re.sub(r'\s+',' ',text[max(0,i-250):i+600])[:850])", "display_text": "Extracting exact support for accessibility, rehearsal, audience adaptation, and Q&A findings"}

